3	const isNeighbor = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
4	  Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1 && !(x1 === x2 && y1 === y2);
5	
6	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
7	  liveCells.filter(
8	    (cell) => liveCells.filter((other) => isNeighbor(cell, other)).length === 2,
9	  );
